import calendar
import re
from bisect import bisect_left
from datetime import date, datetime

_NUM_RE = re.compile(r"[0-9]+")
_SEP_RE = re.compile(r"[ \t]+")

_MONTH_NAMES = {
    name: index
    for index, name in enumerate(
        ["JAN", "FEB", "MAR", "APR", "MAY", "JUN",
         "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"],
        start=1,
    )
}
_DOW_NAMES = {
    name: index
    for index, name in enumerate(["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"])
}


def _parse_value(token, low, high, names):
    if _NUM_RE.fullmatch(token):
        value = int(token)
    elif (
        names is not None
        and token.isascii()
        and token.isalpha()
        and token.upper() in names
    ):
        value = names[token.upper()]
    else:
        raise ValueError(f"invalid value: {token!r}")
    if not low <= value <= high:
        raise ValueError(f"value out of range: {token!r}")
    return value


def _parse_field(text, low, high, names):
    if text == "":
        raise ValueError("empty field")
    values = set()
    for item in text.split(","):
        if item == "":
            raise ValueError("empty item")
        base = item
        step = None
        if "/" in item:
            base, step_text = item.split("/", 1)
            if not _NUM_RE.fullmatch(step_text):
                raise ValueError(f"invalid step: {item!r}")
            step = int(step_text)
            if step < 1:
                raise ValueError(f"invalid step: {item!r}")
        if base == "*":
            start, end = low, high
        elif "-" in base:
            parts = base.split("-")
            if len(parts) != 2:
                raise ValueError(f"invalid range: {item!r}")
            start = _parse_value(parts[0], low, high, names)
            end = _parse_value(parts[1], low, high, names)
            if start > end:
                raise ValueError(f"invalid range: {item!r}")
        else:
            if step is not None:
                raise ValueError(f"step without range: {item!r}")
            start = end = _parse_value(base, low, high, names)
        values.update(range(start, end + 1, step if step is not None else 1))
    return values


def _parse_expression(expression):
    stripped = expression.strip(" \t\r\n")
    fields = _SEP_RE.split(stripped)
    if len(fields) != 5:
        raise ValueError("expression must have exactly 5 fields")
    minute_text, hour_text, dom_text, month_text, dow_text = fields
    minutes = _parse_field(minute_text, 0, 59, None)
    hours = _parse_field(hour_text, 0, 23, None)
    doms = _parse_field(dom_text, 1, 31, None)
    months = _parse_field(month_text, 1, 12, _MONTH_NAMES)
    dows_raw = _parse_field(dow_text, 0, 7, _DOW_NAMES)
    dows = {0 if value == 7 else value for value in dows_raw}
    dom_any = dom_text == "*"
    dow_any = dow_text == "*"
    return minutes, hours, doms, months, dows, dom_any, dow_any


def next_run(expression: str, after: datetime) -> datetime | None:
    minutes, hours, doms, months, dows, dom_any, dow_any = _parse_expression(expression)
    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    limit_year = min(after.year + 10, 9999)
    year = after.year
    month = after.month
    day = after.day
    start_minute = after.hour * 60 + after.minute + 1

    while year <= limit_year:
        if month in months:
            days_in_month = calendar.monthrange(year, month)[1]
            for day_number in range(day, days_in_month + 1):
                if start_minute < 1440:
                    dom_ok = day_number in doms
                    cron_dow = (date(year, month, day_number).weekday() + 1) % 7
                    dow_ok = cron_dow in dows
                    if dom_any and dow_any:
                        matched = True
                    elif dom_any:
                        matched = dow_ok
                    elif dow_any:
                        matched = dom_ok
                    else:
                        matched = dom_ok or dow_ok
                    if matched:
                        index = bisect_left(times, start_minute)
                        if index < len(times):
                            found = times[index]
                            return datetime(year, month, day_number, found // 60, found % 60)
                start_minute = 0
        start_minute = 0
        day = 1
        month += 1
        if month > 12:
            month = 1
            year += 1
    return None
